/// Groups anagrams; words sorted inside each group, groups sorted by their first word.
pub fn group_anagrams(words: List[Str]) -> List[List[Str]] {
  let groups = words.group_by(fn(w) => w.chars().sort().join(""))
  let sorted_groups = groups.values().map(fn(g) => g.sort())
  return sorted_groups.sort_by(fn(g) => g.get_or(0, ""))
}
